import hashlib

# Example of deterministic salt generation from username
def generate_salt_from_username(username: str) -> bytes:
    return hashlib.sha256(username.encode()).digest()

# Example of hashing password with generated salt
def hash_password_with_salt(password: str, salt: bytes) -> bytes:
    return hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 10000)

# Test with a sample username and password
username = "user123"
password = "securepassword"
salt = generate_salt_from_username(username)
hashed = hash_password_with_salt(password, salt)
print(f"Salt: {salt}, Hashed Password: {hashed}")
